# ── 184: Electrical Safety in the OR ─────────────────────────────────────────
kps += [
  {"id":"electrical-safety-or-1","topic":"Electrical Safety in the OR","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"What is the most common risk factor for surgical fires?","answer":"Open delivery of oxygen — administration of O2 >30% in close proximity to an ignition source, especially for procedures above the xiphoid","rationale":"Oxygen enrichment of the surgical field creates the oxidizer leg of the fire triad; face/airway procedures with open O2 delivery are the most common scenario.","bloom":"recall","source":[{"book":"Morgan & Mikhail","page":32}],"confusable_with":"electrosurgery unit as the primary fire cause"},
  {"id":"electrical-safety-or-2","topic":"Electrical Safety in the OR","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"When a surgical fire occurs in the airway, what two actions must be taken simultaneously?","answer":"Stop gas flow AND remove the endotracheal tube — both actions are equally important and neither should be delayed for the other","rationale":"Continuing gas flow sustains the fire; the tube maintains the conduit for combustion; simultaneous action minimizes ongoing thermal injury.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":32}],"confusable_with":"stopping gas flow first then extubating"},
  {"id":"electrical-safety-or-3","topic":"Electrical Safety in the OR","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"What is leakage current and why is it hazardous in the OR?","answer":"Leakage current is present in all electrical equipment via capacitive coupling; small potential differences between OR outlet grounds can cause microelectrocution — current through the heart may trigger fibrillation","rationale":"In an isolated power system, patients connected to multiple devices are at risk if ground potential differences exist; even small currents delivered directly to the heart can cause ventricular fibrillation.","bloom":"analyze","source":[{"book":"Morgan & Mikhail","page":44}],"confusable_with":"macroshock from high-voltage contact"},
  {"id":"electrical-safety-or-4","topic":"Electrical Safety in the OR","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"When using electrosurgery in a patient with an implanted cardiac device (pacemaker/ICD), where should the return electrode be placed?","answer":"As close to the surgical field and as far from the implanted device as practical, to minimize current flow through the cardiac device","rationale":"High-frequency ESU current follows the path of least resistance; routing current away from the device prevents inappropriate sensing, device reset, or delivery of inappropriate therapies.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":49}],"confusable_with":"placing return electrode for patient comfort"}
]

# ── 185: Electrocardiography in Anesthesia ───────────────────────────────────
